def main():
    d = json.loads(F.read_text(encoding="utf-8"))
    have = {u["ref"] for u in d["units"]}
    tmpl = next(u for u in d["units"] if u["ref"] == "12")
    for n in sorted(int(k) for k in SA):
        ref = str(n)
        if ref in have:
            continue
        u = {k: tmpl[k] for k in tmpl if k not in ("ref", "sanskrit", "english", "parts", "meta")}
        u.update(ref=ref, sanskrit=SA[str(n)], english=EN[str(n)])
        d["units"].append(u)
    d["units"].sort(key=lambda u: (0, int(u["ref"])) if u["ref"].isdigit() else (1, 0))
    d["notes"] += " [2026-10-09: sections 7, 28, 36, 46, 52, 53, 54 and 68 restored by re-reading the book's pages with the local indic-ocr model.]"
    if not DRY:
        F.write_text(json.dumps(d, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
